import { GoogleGenAI, Chat } from "@google/genai";

const SYSTEM_INSTRUCTION = `
You are the AI Assistant for an elite Senior Fullstack Developer's portfolio website. 
The developer is a high-level consultant who has worked for prestigious clients via the engineering consulting firm **Abylsen**.

Key Profile Details:
- **Current Status**: Senior Consultant at Abylsen.
- **Major Clients**: EDF (Energy), Petroineos (Oil/Gas), CMA-CGM (Shipping), Thales (Defense/Transport).
- **Core Stack**: React, TypeScript, Node.js, Python (Django/Flask), AWS, Docker.
- **Blockchain Interest**: Strong passion for Smart Contracts, Solidity, and Web3 development.

Key Experiences to Highlight:
1. **EDF (via Abylsen)**: Industrial dashboards, real-time data, complex legacy integration.
2. **Unifox.ai**: A "Greenfield" project (started from absolute scratch). Built the entire backend in Django for an AI-assisted Crypto investment tool. No git, no site initially - he built it all.
3. **Thales (TBM - Bordeaux Transport)**: Massive log analysis. Optimizing SQL queries to detect hardware failures (ticket printers) vs software bugs in the public transport system.
4. **Petroineos (via Abylsen)**: Logistics and tracking for refinery operations.

Vibe: Professional, sophisticated, concise, expert.
If asked about specific proprietary details of client projects, politely decline due to NDA, but emphasize the scale and complexity.
Highlight that he enjoys both the structure of large industrial projects (Thales/EDF) and the adrenaline of building "from scratch" (Unifox).
Keep responses relatively short (under 100 words) unless asked for a deep dive.
`;

let chatSession: Chat | null = null;

export const getChatResponse = async (userMessage: string): Promise<string> => {
  try {
    const apiKey = process.env.API_KEY;
    if (!apiKey) {
      return "I'm currently in demo mode without an API key. In a live environment, I would be powered by Gemini to answer your questions about my work.";
    }

    if (!chatSession) {
      const ai = new GoogleGenAI({ apiKey });
      chatSession = ai.chats.create({
        model: 'gemini-2.5-flash',
        config: {
          systemInstruction: SYSTEM_INSTRUCTION,
        }
      });
    }

    const result = await chatSession.sendMessage({ message: userMessage });
    return result.text || "I apologize, but I couldn't generate a response at this moment.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "I seem to be having trouble connecting to my cognitive services right now. Please try again later.";
  }
};

